from pathlib import Path
from markdown import Markdown
import re

ROOT = Path(__file__).resolve().parents[1]
src = ROOT / 'docs/01-product/PRD.md'
out = ROOT / 'docs/01-product/PRD.html'
raw_text = src.read_text(encoding='utf-8')
text = re.sub(r'^# [^\n]+\n+## Product Requirements Document \(PRD\)\n+', '', raw_text, count=1)
md = Markdown(
    extensions=['extra', 'toc', 'sane_lists'],
    extension_configs={'toc': {'toc_depth': '2-2', 'permalink': False}},
)
body = md.convert(text)
toc = md.toc
requirements = len(set(re.findall(r'`([A-Z]+-\d{2,3})`', raw_text)))
sections = len(re.findall(r'^## ', text, flags=re.M))

css = r'''
:root{--bg:#f2f0e9;--paper:#fffdf8;--ink:#18211c;--muted:#68726c;--line:#d9ddd8;--forest:#123b2f;--teal:#08765a;--mint:#a7dbc8;--amber:#d58b43;--rust:#ad4a32;--navy:#243f51;--code:#10231c;--shadow:0 20px 70px rgba(18,59,47,.09);color-scheme:light}
*{box-sizing:border-box}html{scroll-behavior:smooth;background:var(--bg)}body{margin:0;background:linear-gradient(135deg,rgba(8,118,90,.06),transparent 38rem),var(--bg);color:var(--ink);font-family:Tahoma,"Segoe UI",Arial,sans-serif;font-size:16px;line-height:1.87;direction:rtl;text-align:right}a{color:var(--teal);text-underline-offset:.2em}a:hover{color:var(--rust)}a:focus-visible,button:focus-visible{outline:3px solid #ffb000;outline-offset:3px}.skip{position:fixed;top:.5rem;right:.5rem;transform:translateY(-180%);z-index:100;background:white;color:black;padding:.6rem 1rem;border-radius:.4rem}.skip:focus{transform:none}.progress{position:fixed;z-index:90;top:0;right:0;height:4px;width:0;background:var(--amber)}.hero{position:relative;overflow:hidden;background:var(--forest);color:white;border-bottom:8px solid var(--amber);padding:3.5rem clamp(1rem,5vw,5rem) 2.8rem}.hero:after{content:"PRD";position:absolute;left:4vw;bottom:-.25em;font:900 clamp(7rem,20vw,18rem)/.8 Arial,sans-serif;color:rgba(255,255,255,.035);letter-spacing:-.07em}.hero-inner{position:relative;z-index:1;max-width:1450px;margin:auto}.eyebrow{font-size:.78rem;font-weight:800;letter-spacing:.11em;color:#b9e6d6;margin:0 0 .5rem}.hero h1{font-size:clamp(2.4rem,5.6vw,5.2rem);line-height:1.08;margin:0;max-width:1050px}.hero h1 span{display:block;font-size:.31em;color:#b9e6d6;letter-spacing:.08em;margin-top:.45rem}.hero .lead{max-width:900px;color:#dcebe5;font-size:clamp(1rem,2vw,1.22rem);line-height:1.7;margin:1rem 0}.pills{display:flex;gap:.55rem;flex-wrap:wrap}.pill{border:1px solid rgba(255,255,255,.25);border-radius:999px;padding:.27rem .68rem;font-size:.8rem;color:#f4faf7}.actions{display:flex;gap:.55rem;flex-wrap:wrap;margin-top:1.15rem}.actions button,.actions a{font:inherit;font-size:.83rem;border:1px solid #b9cec4;background:#fff;color:#173c31;padding:.48rem .74rem;border-radius:.38rem;text-decoration:none;cursor:pointer}.layout{max-width:1580px;margin:0 auto;display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:2rem;padding:2rem clamp(.7rem,3vw,3rem) 5rem}.content{min-width:0;background:var(--paper);padding:clamp(1.1rem,4vw,4rem);border:1px solid var(--line);box-shadow:var(--shadow)}.side{grid-column:2;grid-row:1;min-width:0}.tocbox{position:sticky;top:1rem;max-height:calc(100vh - 2rem);overflow:auto;background:rgba(255,253,248,.97);border:1px solid var(--line);padding:1rem 1.1rem}.tocbox>strong{display:block;color:var(--forest);margin-bottom:.5rem}.tocbox .hint{display:block;color:var(--muted);font-size:.74rem;margin-bottom:.65rem}.toc ul{list-style:none;padding:0;margin:0}.toc li{margin:.15rem 0}.toc a{display:block;text-decoration:none;color:#48564f;padding:.18rem 0;font-size:.79rem;line-height:1.46}.toc a:hover{color:var(--teal)}h2,h3,h4{scroll-margin-top:1rem;line-height:1.38}h2{font-size:1.72rem;color:var(--forest);margin-top:3.5rem;border-bottom:2px solid #cfd9d3;padding-bottom:.55rem}h2:first-child{margin-top:0}h3{font-size:1.27rem;color:#285044;margin-top:2.35rem}h4{font-size:1.06rem;margin-top:1.8rem}p{margin:.72rem 0 1rem}strong{color:#123227}blockquote{margin:1.35rem 0;background:#edf7f2;border-inline-start:5px solid var(--teal);padding:.82rem 1.05rem;color:#254138}blockquote p{margin:.15rem 0}hr{border:0;border-top:1px solid var(--line);margin:3rem 0}ul,ol{padding-inline-start:1.5rem}li{margin:.31rem 0}li::marker{color:var(--teal)}code{direction:ltr;unicode-bidi:embed;background:#edf1ee;border:1px solid #dde4df;border-radius:.25rem;padding:.07em .35em;font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:.88em;color:#214b3e}pre{direction:ltr;text-align:left;overflow:auto;background:var(--code);color:#dff7ed;border-radius:.5rem;padding:1rem 1.15rem;border-inline-start:5px solid #3db58a;line-height:1.58}pre code{background:transparent;color:inherit;border:0;padding:0;unicode-bidi:normal}table{border-collapse:separate;border-spacing:0;width:100%;display:block;overflow-x:auto;margin:1.15rem 0 1.8rem;font-size:.88rem;border:1px solid var(--line);border-radius:.35rem}thead{background:#e7f0eb}th,td{border-inline-end:1px solid var(--line);border-bottom:1px solid var(--line);padding:.64rem .72rem;vertical-align:top;min-width:8.5rem}th:last-child,td:last-child{border-inline-end:0}tr:last-child td{border-bottom:0}th{text-align:right;color:#173d31;font-weight:800}tr:nth-child(even) td{background:#faf9f5}td:first-child code{white-space:nowrap;color:#7c3b28;background:#f8eee9;border-color:#ead8cf;font-weight:700}.footer{max-width:1580px;margin:auto;padding:0 2rem 3rem;color:var(--muted);font-size:.82rem}.top{position:fixed;left:1rem;bottom:1rem;width:2.8rem;height:2.8rem;border-radius:50%;border:0;background:var(--forest);color:white;box-shadow:0 8px 25px rgba(0,0,0,.2);cursor:pointer;font-size:1.1rem}
@media(max-width:1080px){.layout{grid-template-columns:1fr}.side{grid-column:1;grid-row:1}.tocbox{position:static;max-height:25rem}.content{grid-row:2}.toc>ul{columns:2;column-gap:1.4rem}.toc li{break-inside:avoid}}
@media(max-width:650px){body{font-size:15px}.hero{padding:2.3rem 1rem 1.8rem}.hero h1{font-size:2.5rem}.layout{padding:1rem .55rem 4rem;gap:1rem}.content{padding:1rem;border-inline:0}.toc>ul{columns:1}h2{font-size:1.43rem;margin-top:2.7rem}th,td{min-width:10rem}.top{display:none}.hero:after{display:none}}
@media print{body{background:#fff;font-size:9.5pt}.progress,.side,.top,.skip,.actions,.pills,.hero .lead,.hero .eyebrow,.hero:after{display:none}.hero{background:#fff;color:#000;border:0;padding:0 0 1rem}.hero h1{font-size:24pt}.hero h1 span{color:#333}.layout{display:block;max-width:none;padding:0}.content{border:0;box-shadow:none;padding:0}h2{break-before:page;margin-top:0}h3{break-after:avoid}table,pre,blockquote{break-inside:avoid}table{font-size:8.2pt}pre{white-space:pre-wrap;background:#f4f4f4;color:#000;border:1px solid #aaa}a{color:#000;text-decoration:none}.footer{padding:1rem 0}}
'''

doc = f'''<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="وثيقة متطلبات المنتج التنفيذية لمنصة نَسَق AI."><title>نَسَق AI — وثيقة متطلبات المنتج PRD</title><style>{css}</style></head><body><div id="progress" class="progress" aria-hidden="true"></div><a class="skip" href="#prd">تجاوز الفهرس إلى الوثيقة</a><header class="hero"><div class="hero-inner"><p class="eyebrow">PRODUCT REQUIREMENTS DOCUMENT · الإصدار 0.1</p><h1>وثيقة متطلبات نَسَق <span>NASAQ AI · PRD</span></h1><p class="lead">تحويل الرؤية إلى نطاق وإصدارات ومتطلبات قابلة للتتبّع والاختبار — من Frontend prototype شامل إلى Backend MVP مضبوط.</p><div class="pills"><span class="pill">{sections} قسمًا</span><span class="pill">{requirements} معرف متطلب وقرار</span><span class="pill">Frontend → Alpha → Beta</span><span class="pill">Arabic-first · RTL/LTR</span></div><div class="actions"><button id="print" type="button">طباعة / حفظ PDF</button><a href="PRD.md">نسخة Markdown</a></div></div></header><div class="layout"><aside class="side"><nav class="tocbox" aria-label="فهرس الوثيقة"><strong>فهرس PRD</strong><span class="hint">انقر للانتقال إلى القسم</span>{toc}</nav></aside><main id="prd" class="content">{body}</main></div><footer class="footer">PRD 0.1 · مسودة تنفيذية. المبالغ والمزودون والسياسات القانونية المفتوحة لا تُعامل كوعود إطلاق حتى اعتمادها.</footer><button id="top" class="top" type="button" aria-label="العودة إلى أعلى">↑</button><script>document.getElementById('print').onclick=()=>window.print();document.getElementById('top').onclick=()=>window.scrollTo({{top:0,behavior:'smooth'}});const p=document.getElementById('progress');addEventListener('scroll',()=>{{const d=document.documentElement;p.style.width=((d.scrollTop/(d.scrollHeight-d.clientHeight||1))*100)+'%'}});</script></body></html>'''
out.write_text(doc, encoding='utf-8')
print(out, out.stat().st_size, 'bytes', requirements, 'tracked IDs')
